182	     * Initialise an instance of this class for a particular quiz attempt.
183	     *
184	     * @param quiz_attempt $attemptobj the attempt to summarise.
185	     * @param display_options $options options for what can be seen.
186	     * @param int|null $pageforlinkingtootherattempts if null, no links to other attempsts will be created.
187	     *      If specified, the URL of this particular page of the attempt, otherwise
188	     *      the URL will go to the first page.  If -1, deduce $page from $slot.
189	     * @param bool|null $showall if true, the URL will be to review the entire attempt on one page,
190	     *      and $page will be ignored. If null, a sensible default will be chosen.
191	     * @return self summary information.
192	     */
193	    public static function create_for_attempt(
194	        quiz_attempt $attemptobj,
195	        display_options $options,
196	        ?int $pageforlinkingtootherattempts = null,
197	        ?bool $showall = null,
198	    ): static {
199	        global $DB, $USER;
200	        $summary = new static();
201	
202	        // Prepare summary information about the whole attempt.
203	        if (!$attemptobj->get_quiz()->showuserpicture && $attemptobj->get_userid() != $USER->id) {
204	            // If showuserpicture is true, the picture is shown elsewhere, so don't repeat it.
205	            $student = $DB->get_record('user', ['id' => $attemptobj->get_userid()]);
206	            $userpicture = new user_picture($student);
207	            $userpicture->courseid = $attemptobj->get_courseid();
208	            $summary->add_item('user', $userpicture,
209	                new action_link(
210	                    new moodle_url('/user/view.php', ['id' => $student->id, 'course' => $attemptobj->get_courseid()]),
211	                    fullname($student, true),
212	                )
213	            );
214	        }
215	
216	        if ($pageforlinkingtootherattempts !== null && $attemptobj->has_capability('mod/quiz:viewreports')) {
217	            $attemptlist = $attemptobj->links_to_other_attempts(
218	                $attemptobj->review_url(null, $pageforlinkingtootherattempts, $showall));
219	            if ($attemptlist) {
220	                $summary->add_item('attemptlist', get_string('attempts', 'quiz'), $attemptlist);
221	            }
222	        }
223	
224	        // Caption.
225	        $summary->set_caption(get_string('summaryofattemptscaption', 'quiz', $attemptobj->get_attempt_number()));
226	
227	        // Attempt state.
228	        $summary->add_item('state', get_string('attemptstate', 'quiz'),
229	            quiz_attempt::state_name($attemptobj->get_attempt()->state));
230	
231	        // Timing information.
232	        $attempt = $attemptobj->get_attempt();
233	        $quiz = $attemptobj->get_quiz();
234	        $overtime = 0;
235	
236	        if ($attempt->state == quiz_attempt::FINISHED) {
237	            if ($timetaken = ($attempt->timefinish - $attempt->timestart)) {
238	                if ($quiz->timelimit && $timetaken > ($quiz->timelimit + 60)) {
239	                    $overtime = $timetaken - $quiz->timelimit;
240	                    $overtime = format_time($overtime);
241	                }
242	                $timetaken = format_time($timetaken);
243	            } else {
244	                $timetaken = "-";
245	            }
246	        } else {
247	            $timetaken = get_string('unfinished', 'quiz');
248	        }
249	
250	        $summary->add_item('startedon', get_string('startedon', 'quiz'), userdate($attempt->timestart));
251	
252	        if ($attempt->state == quiz_attempt::FINISHED) {
253	            $summary->add_item('completedon', get_string('completedon', 'quiz'),
254	                userdate($attempt->timefinish));
255	            $summary->add_item('timetaken', get_string('attemptduration', 'quiz'), $timetaken);
256	        }
257	
258	        if (!empty($overtime)) {
259	            $summary->add_item('overdue', get_string('overdue', 'quiz'), $overtime);
260	        }
261	
262	        // Show marks (if the user is allowed to see marks at the moment).
263	        $grade = $summary->add_attempt_grades_if_appropriate($attemptobj, $options);
264	
265	        // Any additional summary data from the behaviour.
266	        foreach ($attemptobj->get_additional_summary_data($options) as $shortname => $data) {
267	            $summary->add_item($shortname, $data['title'], $data['content']);
268	        }
269	
270	        // Feedback if there is any, and the user is allowed to see it now.
271	        $feedback = $attemptobj->get_overall_feedback($grade);
272	        if ($options->overallfeedback && $feedback) {
273	            $summary->add_item('feedback', get_string('feedback', 'quiz'), $feedback);
274	        }
275	
276	        return $summary;
277	    }
