283	     *
284	     * @param quiz_attempt $attemptobj the attempt to summarise.
285	     * @param display_options $options options for what can be seen.
286	     * @return float|null the overall attempt grade, if it exists, else null. Raw value, not formatted.
287	     */
288	    public function add_attempt_grades_if_appropriate(
289	        quiz_attempt $attemptobj,
290	        display_options $options,
291	    ): ?float {
292	        $quiz = $attemptobj->get_quiz();
293	        $grade = quiz_rescale_grade($attemptobj->get_sum_marks(), $quiz, false);
294	
295	        if ($options->marks < question_display_options::MARK_AND_MAX) {
296	            // User can't see grades.
297	            return $grade;
298	        }
299	
300	        if (!quiz_has_grades($quiz) || $attemptobj->get_state() != quiz_attempt::FINISHED) {
301	            // No grades to show.
302	            return $grade;
303	        }
304	
305	        if (is_null($grade)) {
306	            // Attempt needs ot be graded.
307	            $this->add_item('grade', get_string('gradenoun'), quiz_format_grade($quiz, $grade));
308	            return $grade;
309	        }
310	
311	        // Grades for extra grade items, if any.
312	        foreach ($attemptobj->get_grade_item_totals() as $gradeitemid => $gradeoutof) {
313	            $this->add_item('marks' . $gradeitemid, format_string($gradeoutof->name),
314	                new grade_out_of($quiz, $gradeoutof->grade, $gradeoutof->maxgrade,
315	                    style: abs($gradeoutof->maxgrade - 100) < grade_calculator::ALMOST_ZERO ?
316	                        grade_out_of::NORMAL : grade_out_of::WITH_PERCENT));
317	        }
