        $resultinfo .= $this->heading(get_string('overallfeedback', 'quiz'), 3);
        $resultinfo .= html_writer::div(
                        quiz_feedback_for_grade($viewobj->mygrade, $quiz, $context),
                        'quizgradefeedback') . "\n";
    }

    if ($resultinfo) {
        $output .= $this->box($resultinfo, 'generalbox', 'feedback');
    }
    return $output;
}

